import{_ as n,C as r,o,c as h,j as t,a as d,E as s,a5 as i}from"./chunks/framework.-jms6n7v.js";const b=JSON.parse('{"title":"Performance","description":"How fast DaruDB reads and writes next to the embedded databases each of its languages uses most, measured with the benchmark in the repository: the same…","frontmatter":{"title":"Performance","order":3,"aside":false,"pageClass":"performance-page","prev":{"text":"Comparison","link":"/compare"},"next":{"text":"Migration","link":"/migration/"}},"headers":[{"level":2,"title":"What is measured","slug":"what-is-measured","link":"#what-is-measured","children":[]},{"level":2,"title":"How it is kept fair","slug":"how-it-is-kept-fair","link":"#how-it-is-kept-fair","children":[]},{"level":2,"title":"Next to Realm","slug":"next-to-realm","link":"#next-to-realm","children":[]},{"level":2,"title":"Where DaruDB is behind, and why","slug":"where-darudb-is-behind-and-why","link":"#where-darudb-is-behind-and-why","children":[]},{"level":2,"title":"The complex suite","slug":"the-complex-suite","link":"#the-complex-suite","children":[{"level":3,"title":"What it measures","slug":"what-it-measures","link":"#what-it-measures","children":[]},{"level":3,"title":"Where DaruDB is behind in the complex suite","slug":"where-darudb-is-behind-in-the-complex-suite","link":"#where-darudb-is-behind-in-the-complex-suite","children":[]}]},{"level":2,"title":"Run it yourself","slug":"run-it-yourself","link":"#run-it-yourself","children":[]}],"relativePath":"performance.md","filePath":"en/performance.md","lastUpdated":1794984995000}'),l={name:"performance.md"};function c(u,e,m,p,f,g){const a=r("PerformanceTable");return o(),h("div",null,[e[0]||(e[0]=t("h1",{id:"performance",tabindex:"-1"},[d("Performance "),t("a",{class:"header-anchor",href:"#performance","aria-label":'Permalink to "Performance"'},"​")],-1)),e[1]||(e[1]=t("p",null,"How fast DaruDB reads and writes next to the embedded databases each of its languages uses most, measured with the benchmark in the repository: the same objects and workloads in every database, at the same durability settings, on one machine.",-1)),e[2]||(e[2]=t("p",null,"The table follows the language chosen in the sidebar. The stores of one language ran one after another, so their times compare with each other. Every language ran on the same machine, each in a run of its own.",-1)),s(a),e[3]||(e[3]=i('<h2 id="what-is-measured" tabindex="-1">What is measured <a class="header-anchor" href="#what-is-measured" aria-label="Permalink to &quot;What is measured&quot;">​</a></h2><p>One collection of 100,000 objects, each with a name, an email under a unique index, an age under an index, a city and a score, both without an index. Every row times many operations and divides by their number:</p><table tabindex="0"><thead><tr><th>Workload</th><th>What it does</th></tr></thead><tbody><tr><td>Insert, one object per sync commit</td><td>500 commits of one object, each waiting for the disk</td></tr><tr><td>Insert, one object per deferred commit</td><td>10,000 commits of one object, each leaving the sync for later</td></tr><tr><td>Insert 100,000 objects in one transaction</td><td>Every object, the commit included</td></tr><tr><td>Get by primary key, random order</td><td>100,000 reads of one object</td></tr><tr><td>Get by a unique index, random order</td><td>20,000 reads of one object through the email</td></tr><tr><td>Query an indexed value, 1,250 objects</td><td>The objects of one age</td></tr><tr><td>Query an indexed range, sorted, first 20</td><td>The first 20 objects of five ages, sorted by age descending, then by key</td></tr><tr><td>Count through an index</td><td>The objects with an age of 40 or more</td></tr><tr><td>Query without an index, 1,000 objects</td><td>The objects of one city, ten times over</td></tr><tr><td>Query without an index, 1,000 objects, first run</td><td>The first of those ten</td></tr><tr><td>Top 10 by a field without an index</td><td>The 10 objects with the highest score, ten times over</td></tr><tr><td>Top 10 by a field without an index, first run</td><td>The first of those ten</td></tr><tr><td>Read and update 10,000 objects</td><td>Each read, given a new age and written back, in one transaction with its commit</td></tr><tr><td>Delete 10,000 objects</td><td>In one transaction with its commit</td></tr></tbody></table><p>The two queries without an index each have a row of their own for their first run, since DaruDB answers such a query faster once it has run: it remembers where the field it tests or sorts by lies in each record it read, and reads it there the next time. A query that an application runs once takes the time of the first run.</p><p>Every database is used the way an application in that language would use it. DaruDB runs through its public API with a schema, SQLite through SQL with prepared statements, and the key-value stores keep a record and the indexes an application would write for them. Every read is made into an object of the language with all its fields, and a query that runs many times is prepared once. An update sets the one field it changes, as SQL sets one column: through Node.js, Python and Dart with <code>update</code>, where writing the whole object back would build it again in the language first, and through Rust with <code>TypedWriter::set</code>, which names the field through the type.</p><p>The Node.js and Dart tables also have Realm, for applications moving from it, though its vendor deprecated it in September 2024 and ended support in September 2025; the <a href="./migration/realm">migration guide</a> shows how to move the data. Realm assigns no keys, so the application gives each object the key the other stores assign. It has no unique index besides the primary key, so the email has a plain index, and its queries are strings it parses on every call, since it has no prepared queries. An update sets the one property.</p><h2 id="how-it-is-kept-fair" tabindex="-1">How it is kept fair <a class="header-anchor" href="#how-it-is-kept-fair" aria-label="Permalink to &quot;How it is kept fair&quot;">​</a></h2><ul><li><strong>The same durability.</strong> A sync commit waits until the disk has it: DaruDB&#39;s default commit, SQLite&#39;s write-ahead log with <code>synchronous = FULL</code>, LMDB&#39;s default commit, redb&#39;s <code>Durability::Immediate</code>, Hive&#39;s write followed by <code>flush</code>, and Realm&#39;s commit. A deferred commit returns before that: DaruDB&#39;s deferred commit, <code>synchronous = NORMAL</code>, LMDB&#39;s <code>NO_SYNC</code>, redb&#39;s <code>Durability::None</code> and Hive&#39;s write alone. Realm has no commit that leaves the sync for later, so its cell in that row is empty. redb&#39;s promises less than the others, since nothing it writes is durable until a later immediate commit.</li><li><strong>The same work.</strong> Every row hashes the keys and ages of what it found, in the order it found them, and a run in which two databases disagree fails rather than giving a time.</li><li><strong>A clean start.</strong> Each pass of each database runs in a process of its own, on new files, and the databases take turns in an order that changes every run. A time is the median of the runs.</li><li><strong>The same machine.</strong> The databases of one language run on one machine, one after another.</li></ul><p>The cache each database may use is left at its default, apart from DaruDB&#39;s and SQLite&#39;s, which are both set to 32 MiB. A database that keeps every object in memory, as Hive does, reads without touching its file.</p><p>The tables were measured on one Apple M1 Max with 10 cores and 32 GiB of memory, under macOS 27.2, with the files on its internal SSD. On Apple systems a sync commit of DaruDB, LMDB and redb, and of SQLite with <code>fullfsync</code>, ends with <code>F_FULLFSYNC</code>, which waits until the drive has written its own cache. DaruDB&#39;s sync commit takes 4.1 to 4.9 ms here, nearly all of it that wait, since the same commit deferred takes 35 to 48 µs. Hive&#39;s <code>flush</code> is an <code>fsync</code>, which on Apple systems reaches only the drive&#39;s cache, and Realm&#39;s commit is an <code>F_BARRIERFSYNC</code>, which keeps writes in order across a power cut but does not wait for the drive to have them. Their sync commits take a fraction of the others&#39; time here and promise less, since a power cut can undo them.</p><p>The <code>run-benchmarks</code> workflow measures on GitHub-hosted Linux runners instead. Those runners mount their disk without write barriers, so a sync commit there waits for the file system&#39;s work but not for the disk&#39;s own cache, and their processors and disks differ from one run to the next, which moves the commit rows most. Compare a commit row&#39;s databases within one table only.</p><h2 id="next-to-realm" tabindex="-1">Next to Realm <a class="header-anchor" href="#next-to-realm" aria-label="Permalink to &quot;Next to Realm&quot;">​</a></h2><p>For an application moving from Realm, the Node.js and Dart tables are the ones to read; choose Node.js or Dart in the sidebar to see them. DaruDB is ahead of Realm in every row but the sync commit, the first run of the query of one city, a field without an index, and the update. Realm&#39;s sync commit takes 0.17 times DaruDB&#39;s time in Node.js and 0.13 times in Dart, since on Apple systems it does not wait for the drive to have the commit, as the section above says, and it has no deferred commit. Realm keeps each property&#39;s values together and reads only the city, and takes 0.64 times DaruDB&#39;s time on the first run of that query in Node.js and 0.75 times in Dart; over ten runs it takes 1.39 and 1.12 times, since from the second run on DaruDB reads the city where the first found it in each record. An update sets one field in both, and takes Realm 1.04 times DaruDB&#39;s time in Node.js and 0.68 times in Dart.</p><p>In the other rows, in Node.js and in Dart, Realm takes 7.8 and 4.2 times as long to insert 100,000 objects in one transaction, and 5.2 and 3.5 times to delete 10,000. It takes 4.9 and 2.9 times as long to read by key, and 11 and 6.6 times through the email, since it parses a query string on every call and has no unique index besides the primary key. It takes 4.1 and 4.0 times as long for the objects of one age, 118 and 85 times for the first 20 of five ages, since it sorts every object of the five ages before it takes the first 20, 7.4 and 8.5 times to count through the index, and 1.9 to 3.8 times for the ten objects with the highest score.</p><h2 id="where-darudb-is-behind-and-why" tabindex="-1">Where DaruDB is behind, and why <a class="header-anchor" href="#where-darudb-is-behind-and-why" aria-label="Permalink to &quot;Where DaruDB is behind, and why&quot;">​</a></h2><p>On this machine DaruDB is ahead of every other database in most rows in every language. In Python it is ahead of SQLite in every row but the sync commit, and of LMDB in every row but the deferred commit. In Node.js, LMDB is ahead in the deferred commit, SQLite in the first run of the query of the highest scores, and Realm in the rows the section above names, while SQLite is level with DaruDB in the sync commit, the read through the email, the sorted range and the first run of the query of one city. In Dart, Hive is ahead in the queries without an index, SQLite in the first run of the query of the highest scores, and Realm in the rows above. In Rust, LMDB is ahead in the deferred commit, the sorted range and the queries without an index, and redb in the deferred commit, the read by key, the sorted range and the first run of the query of the highest scores. These are the rows where DaruDB is not ahead, with what makes each slower:</p><ul><li><strong>A sync commit.</strong> Every database that waits for the drive takes 4.1 to 4.9 ms for one here, nearly all of it the wait, and LMDB through Python takes 8.9 ms. In Rust, Node.js and Dart they are within a twentieth of each other. In Python SQLite takes 0.90 times DaruDB&#39;s time, where DaruDB&#39;s runs spread wider, from 4.2 to 8.1 ms. Hive and Realm take 0.03 to 0.17 times DaruDB&#39;s time, since on Apple systems they do not wait for the drive, as the section on fairness says.</li><li><strong>A deferred commit of one object.</strong> LMDB takes 0.61 to 0.82 times DaruDB&#39;s time in Rust, Node.js and Python, and redb 0.68 times in Rust. DaruDB writes about eleven pages in nine or ten calls, each page with its check, and it takes the writer lock with <code>fcntl</code>, reads the header again and releases the lock, since processes coordinate through file locks alone; on an Apple M1 Max the lock and the header are about an eighth of the commit. LMDB writes its pages with no check and coordinates processes through a mutex in shared memory, which DaruDB rejects: a process that dies holding one can leave the others stuck. redb&#39;s <code>Durability::None</code> makes nothing durable until a later immediate commit, so it promises less than the others&#39; deferred commits. SQLite and Hive are behind here, at 1.63 to 2.00 and 1.16 times DaruDB&#39;s time.</li><li><strong>Reads and queries through an index, in Rust.</strong> redb finds an object by its key in 0.88 times DaruDB&#39;s time, and redb and LMDB give the first 20 objects of five ages, sorted, in 0.71 and 0.81 times. A DaruDB lookup finds each page below the root in its page cache, searches the node comparing keys as bytes, and decodes the record, which tags each field with an id, into the struct. redb compares its primary keys as integers, and reads the record written by hand for it, with its fields at fixed places. The sorted range costs more besides: it sorts by age descending and then by key, so DaruDB walks the age index backwards and holds back the objects of each age to give them in key order, where the loop written for the key-value stores asks for each age in turn. In the other reads and queries through an index DaruDB is ahead of both, and LMDB, which reads its file through a memory map, takes 1.06 and 1.14 times its time to read by key and by email. On GitHub&#39;s x86 Linux runners, where finding a page in the cache under its lock takes a larger share of a lookup, LMDB was ahead in those rows too.</li><li><strong>Queries without an index.</strong> LMDB in Rust scans 2.3 to 6.3 times as fast as DaruDB, Hive in Dart 1.2 to 2.8 times, and Realm finds the objects of one city faster on the first run, in Node.js and in Dart. SQLite is ahead on the first run of the query of the highest scores in Node.js and in Dart, at 0.91 and 0.82 times DaruDB&#39;s time, and level on the first runs in Rust, and redb is ahead on that first run in Rust, at 0.84 times. Over ten runs DaruDB is ahead of SQLite, redb and Realm, which take 1.12 to 3.8 times its time. The record written by hand for the key-value stores keeps the age and the score at fixed places, so a scan reads those bytes and decodes only what it returns; Hive scans the objects it keeps in memory; Realm keeps each property&#39;s values together, so a scan reads only the city; and SQLite&#39;s record lists the types of its columns at its start, so finding one column adds up the sizes before it without reading them. A DaruDB record tags each field with an id and a type, which makes renaming a field free and lets the engine check what it reads from a file it does not trust, so a first scan steps over the fields before the one it tests in each record. It remembers where it found the field, and the runs after the first read it there.</li><li><strong>An update in Dart</strong>, where Realm takes 0.68 times DaruDB&#39;s time, and 1.04 times in Node.js. Realm keeps each property&#39;s values together, so setting the age changes that value alone, where DaruDB writes the object&#39;s record again with the new age.</li></ul><h2 id="the-complex-suite" tabindex="-1">The complex suite <a class="header-anchor" href="#the-complex-suite" aria-label="Permalink to &quot;The complex suite&quot;">​</a></h2><p>A second suite measures an application with more than one collection: three collections that link to each other, 401,000 objects in all, and queries through links, lists and several indexes at once. Only the stores with a query language run it, DaruDB, SQLite and, in Node.js and Dart, Realm: a key-value store has no planner, and the code written by hand for each query would be what a row measured, not the store.</p><p>These tables come from the same machine as the ones above, each language&#39;s measured right after its first suite. Each cell is the median of five passes, since a pass takes longer here.</p>',20)),s(a,{suite:"complex"}),e[4]||(e[4]=i(`<h3 id="what-it-measures" tabindex="-1">What it measures <a class="header-anchor" href="#what-it-measures" aria-label="Permalink to &quot;What it measures&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Collection</th><th>Objects</th><th>Fields</th></tr></thead><tbody><tr><td>Organizations</td><td>1,000</td><td>A code as the key, a name, a kind and a country, both indexed, and a year</td></tr><tr><td>People</td><td>100,000</td><td>A name, an email under a unique index, an age, a country and a date joined, each indexed, an embedded address, a score, whether active, a link to an organization, indexed, and a list of one to three tags, indexed</td></tr><tr><td>Posts</td><td>300,000</td><td>A link to the author, indexed, a title, a body of twelve words, likes, a language and a date, each indexed, whether pinned, and a list of up to two tags, indexed</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Workload</th><th>What it does</th></tr></thead><tbody><tr><td>Load 401,000 objects, 10,000 to a transaction</td><td>The three collections, each commit waiting for the disk; the time is per object</td></tr><tr><td>A person, their organization and their 5 newest posts</td><td>By key, then through the link, then through the posts&#39; author index, 10,000 times</td></tr><tr><td>Three conditions on two indexes, sorted, first 50</td><td>An age range of ten years, one country and active, by score descending</td></tr><tr><td>Count with OR across two indexes</td><td>The people of two countries, or aged 78 and over</td></tr><tr><td>Names that start with a text</td><td>The people whose name starts with <code>person</code> and a number below 1,000, a field without an index</td></tr><tr><td>A page of 50, deep in an indexed order</td><td>50 people in the order they joined, after skipping up to 98,703</td></tr><tr><td>Through a link</td><td>The 20 newest posts with 900 likes or more whose author lives in one country</td></tr><tr><td>Through two links</td><td>Counting the posts of one language whose author&#39;s organization is of one kind</td></tr><tr><td>A tag in a list, sorted by another index</td><td>The 20 posts with one tag that have the most likes</td></tr><tr><td>Count posts whose text contains a phrase</td><td>Two words in a row, in the body of 300,000 posts, without an index</td></tr><tr><td>Count with conditions on two indexes</td><td>The posts of one language with 500 likes or more</td></tr><tr><td>Update the people a query finds</td><td>Adding a year to the age of everyone in four countries, about 20,000 people, in one transaction; the time is per person</td></tr><tr><td>Delete 1,000 people with their posts</td><td>In one transaction; the time is per person</td></tr></tbody></table><p>Each store writes its queries the way an application would: DaruDB in its query language, prepared once; SQLite in SQL, with a join or a subquery for a link and a table of tags for each list; Realm in its query language, with a backlink for a person&#39;s posts, since Realm cannot index a link. An update through SQL is one <code>UPDATE</code> statement, where DaruDB and Realm find the people and change each. Every row digests what it found, and a run in which two stores disagree fails, as in the suite above.</p><h3 id="where-darudb-is-behind-in-the-complex-suite" tabindex="-1">Where DaruDB is behind in the complex suite <a class="header-anchor" href="#where-darudb-is-behind-in-the-complex-suite" aria-label="Permalink to &quot;Where DaruDB is behind in the complex suite&quot;">​</a></h3><p>DaruDB is ahead of SQLite in every row but the update in Dart and Python, where SQLite takes 0.64 and 0.91 times DaruDB&#39;s time; in Rust and Node.js it takes 1.38 and 1.26 times. Realm is ahead in three rows in Node.js and five in Dart:</p><ul><li><strong>Counting posts by a phrase in their text, and by conditions on two indexes.</strong> Realm takes 0.45 and 0.82 times DaruDB&#39;s time in Node.js, and 0.45 and 0.71 times in Dart. Realm keeps each property&#39;s values together, so it reads only the bodies, or only the languages and the likes, and counts them without making an object. DaruDB reads each post&#39;s record to find the body in it, and the records of 300,000 posts outgrow the page cache of 32 MiB it has here, so each count reads them from the file again; with a cache that held the file, the count took half the time on an Apple M1 Max. For the count by two conditions it gathers the keys of one condition from its index, then walks the other&#39;s index for those among them.</li><li><strong>Updating the people a query finds.</strong> Realm takes 0.66 times DaruDB&#39;s time in Node.js and 0.57 times in Dart, and SQLite 0.64 times in Dart and 0.91 times in Python. Realm sets one value where it keeps the ages, and SQLite&#39;s one statement changes every row inside the engine. DaruDB finds the people through the country index and changes each one&#39;s record where it lies, with its entries in the age index, 5.1 to 8.3 µs a person.</li><li><strong>Names that start with a text, and posts through a link, in Dart.</strong> Realm takes 0.74 and 0.93 times DaruDB&#39;s time in Dart, and 1.04 and 1.76 times in Node.js. Realm tests the names, or the likes and each author&#39;s country, in the values it keeps together. DaruDB walks every person&#39;s record for the names, a field without an index, and for the posts gathers the keys of the country&#39;s people from its index, follows them to their posts through the author index, meets those with the likes, and walks the date index for the newest.</li></ul><h2 id="run-it-yourself" tabindex="-1">Run it yourself <a class="header-anchor" href="#run-it-yourself" aria-label="Permalink to &quot;Run it yourself&quot;">​</a></h2><p>The harness is in <a href="https://github.com/jooy2/darudb/tree/main/bench" target="_blank" rel="noreferrer"><code>bench/</code></a> of the repository, with a README that lists every setting. The <code>run-benchmarks</code> workflow runs it on GitHub-hosted runners and opens a pull request with the results for this page.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/rust</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../..</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/run.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/results/rust.json</span></span></code></pre></div><p><code>--suite complex</code> runs the complex suite, for which five passes are enough: <code>node bench/run.mjs rust --suite complex --runs 5 --out bench/results/rust-complex.json</code>.</p>`,11))])}const y=n(l,[["render",c]]);export{b as __pageData,y as default};
